import json,glob,os
for f in glob.glob(os.path.expanduser('~/.pi/agent/*.json')):
    try:
        d=json.load(open(f))
    except Exception as e:
        continue
    s=json.dumps(d,ensure_ascii=False)
    if 'orchestra' in s or 'trust' in s.lower():
        print(f, [k for k in (d if isinstance(d,dict) else [])])
EOF

